"""Telegram notifications and channel monitoring UI."""


def telegram_html() -> str:
    return r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Telegram · 影舟 MovieArk</title><style>
:root{--line:#17515a;--gold:#d7b975;--cyan:#29cadc;--muted:#9b907b}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 75% 0,#2c2112,#080705 45%);color:#e6ddc8;font:14px system-ui,"Microsoft YaHei",sans-serif}.shell{display:grid;grid-template-columns:235px 1fr;min-height:100vh}.side{background:#080704ee;border-right:1px solid var(--line);padding:20px 12px}.logo{font-size:21px;font-weight:800;color:var(--gold);padding:6px 10px 28px}.nav{display:block;color:#b9a982;text-decoration:none;padding:13px 15px;border-radius:12px;font-weight:700}.nav:hover,.nav.active{background:#123a40;color:#45d8e8}.group{font-size:11px;color:#776d58;border-bottom:1px solid #3a311f;padding:16px 8px 7px;margin-bottom:5px}.top{height:64px;display:flex;align-items:center;padding:0 28px;border-bottom:1px solid var(--line);font-size:22px;font-weight:800;color:var(--cyan)}.save{margin-left:auto;background:#153a40;color:#58dcea;border:1px solid #26747d;border-radius:9px;padding:9px 16px}.wrap{max-width:1250px;margin:auto;padding:24px}.card{background:#12100b;border:1px solid var(--line);border-radius:15px;padding:20px;margin-bottom:16px}.card h2{color:var(--gold);margin-top:0}.hint{color:var(--muted);margin-bottom:15px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field label{display:block;color:#aa9c84;margin-bottom:6px}.field input,.field textarea{width:100%;border:1px solid #245d65;border-radius:8px;background:#080806;color:#ddd;padding:10px}.field input{height:43px}.field textarea{height:150px}.events{display:flex;flex-wrap:wrap;gap:12px;margin:12px 0}.event{padding:9px 12px;background:#17140e;border:1px solid #4d3d23;border-radius:9px}.actions{display:flex;gap:9px;margin-top:14px}.actions button{padding:9px 14px;border:1px solid #39777d;border-radius:8px;background:#15343a;color:#5bd8e6}.status{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:14px}.metric{background:#0a0907;border:1px solid #3c331f;border-radius:9px;padding:12px}.metric span{display:block;color:var(--muted);font-size:12px}.toast{display:none;position:fixed;right:24px;bottom:24px;padding:13px 17px;border:1px solid #48b67f;background:#15392d;border-radius:9px;color:#c9f6da}.toast.bad{background:#3b1e20;border-color:#b64e55;color:#ffd0d2}@media(max-width:850px){.shell{display:block}.side{display:none}.grid,.status{grid-template-columns:1fr}.wrap{padding:12px}}
</style></head><body><div class="shell"><aside class="side"><div class="logo">◉ 影舟 MovieArk</div><div class="group">发现</div><a class="nav" href="/rankings">🏆 榜单</a><a class="nav" href="/explore">◉ 汇影</a><a class="nav" href="/search">⌕ 搜索</a><div class="group">订阅</div><a class="nav" href="/subscriptions">☷ 订阅列表</a><a class="nav" href="/tasks">▣ 订阅任务</a><a class="nav" href="/unlocks">◴ 解锁记录</a><div class="group">系统</div><a class="nav" href="/authorizations">⌘ 授权中心</a><a class="nav" href="/settings">⚙ 业务设置</a><a class="nav active" href="/telegram">✈ Telegram</a></aside><main><header class="top">✈ Telegram 通知与频道<button id="save" class="save">保存设置</button></header><section class="wrap"><article class="card"><h2>通知机器人</h2><div class="hint">敏感凭据只保存在服务端。可分别启用不同业务事件。</div><div class="grid"><div class="field"><label>Bot Token</label><input id="bot_token" type="password" placeholder="留空表示不修改"></div><div class="field"><label>Chat ID</label><input id="chat_id"></div><div class="field"><label>Telegram API ID</label><input id="api_id" placeholder="用于用户侧搜索授权（可选）"></div><div class="field"><label>API Hash</label><input id="api_hash" type="password" placeholder="留空表示不修改"></div><div class="field"><label>授权用户 ID</label><input id="authorized_user_id" placeholder="仅允许该用户控制机器人"></div></div><label class="event"><input type="checkbox" id="enabled"> 启用 Telegram 通知</label><div class="events" id="events"></div><div class="grid"><div class="field"><label>自定义模板</label><textarea id="template"></textarea></div><div class="field"><label>实时预览</label><textarea id="preview" readonly></textarea></div></div><div class="actions"><button id="test">测试发送</button></div></article><article class="card"><h2>影巢频道自动转存</h2><div class="hint">后台独立定时读取公开频道新消息；单条消息失败不会中断后续检查。</div><div class="grid"><label class="event"><input id="channel_enabled" type="checkbox"> 启用频道监控</label><div class="field"><label>频道地址或用户名</label><input id="channel_name" placeholder="https://t.me/oneonefivewpfx"></div><div class="field"><label>检查周期（秒）</label><input id="channel_interval" type="number" min="60"></div></div><div class="actions"><button id="check">立即检查</button><button id="refresh">刷新状态</button></div><div class="status"><div class="metric"><span>上次检查</span><b id="last_check">-</b></div><div class="metric"><span>最近状态 / 错误</span><b id="last_status">-</b></div><div class="metric"><span>累计处理</span><b id="processed">0</b></div></div></article></section></main></div><div id="toast" class="toast"></div><script>
const $=s=>document.querySelector(s),eventDefs={transfer_success:'转存成功',transfer_failed:'转存失败',subscription:'订阅事件',manual_review:'刮削/人工确认'};let cfg={};function drawEvents(){ $('#events').innerHTML=Object.entries(eventDefs).map(([k,v])=>`<label class="event"><input data-event="${k}" type="checkbox" ${cfg.events?.[k]?'checked':''}> ${v}</label>`).join('')}function preview(){const v={title:'示例影片',status:'转存成功',resource:'影巢资源',resolution:'4K',size:'18.6 GB',save_path:'/影视/待整理',error:''};let t=$('#template').value||'【影舟 MovieArk】{title}\n状态：{status}\n资源：{resource}\n清晰度：{resolution}\n大小：{size}\n保存路径：{save_path}\n{error}';for(const[k,x]of Object.entries(v))t=t.replaceAll('{'+k+'}',x);$('#preview').value=t}async function load(){const r=await fetch('/api/web/telegram/settings'),d=await r.json();if(!r.ok)return toast(d.detail||'加载失败',true);cfg=d;$('#chat_id').value=d.chat_id||'';$('#enabled').checked=!!d.enabled;$('#template').value=d.template||'';$('#channel_enabled').checked=!!d.channel_enabled;$('#channel_name').value=d.channel_name||'';$('#channel_interval').value=d.channel_interval||600;drawEvents();preview();status()}async function save(){const events={};document.querySelectorAll('[data-event]').forEach(x=>events[x.dataset.event]=x.checked);const body={bot_token:$('#bot_token').value,chat_id:$('#chat_id').value,enabled:$('#enabled').checked,events,template:$('#template').value,channel_enabled:$('#channel_enabled').checked,channel_name:$('#channel_name').value,channel_interval:+$('#channel_interval').value};const r=await fetch('/api/web/telegram/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();toast(r.ok?'设置已保存':d.detail||'保存失败',!r.ok);if(r.ok)load()}async function status(){const r=await fetch('/api/web/telegram/channel/status'),d=await r.json();if(!r.ok)return;$('#last_check').textContent=d.last_check?new Date(d.last_check*1000).toLocaleString('zh-CN',{hour12:false}):'尚未检查';$('#last_status').textContent=d.last_error||d.last_status||'等待运行';$('#processed').textContent=d.processed||0}async function action(path){const r=await fetch(path,{method:'POST'}),d=await r.json();toast(d.message||d.detail||'操作完成',!r.ok);status()}function toast(m,b=false){const t=$('#toast');t.textContent=m;t.className='toast'+(b?' bad':'');t.style.display='block';setTimeout(()=>t.style.display='none',3500)}$('#save').onclick=save;$('#test').onclick=()=>action('/api/web/telegram/test');$('#check').onclick=()=>action('/api/web/telegram/channel/check');$('#refresh').onclick=status;$('#template').oninput=preview;load();
</script></body></html>'''
